//! DEV / TEST-ONLY signing key.
//!
//! This seed is public on purpose: it exists so unit tests and the local end-to-end
//! proof can sign a fake release. It is compiled only under `cargo test` or the
//! `test-server` feature (which refuses to build in release mode), so a release build
//! of the updater does not contain it and does not trust it. Never use it for anything
//! real. The real release key is generated by `tools\release-keygen.ps1` and never
//! committed.

use ed25519_compact::{KeyPair, PublicKey, Seed};

/// 32 bytes, hex. TEST ONLY.
pub const DEV_TEST_ONLY_SEED_HEX: &str = "d3a1c0de0000dead00000000007e57000000000000000000d3b007000000cafe";

pub fn dev_keypair() -> KeyPair {
    let b = crate::hash::from_hex(DEV_TEST_ONLY_SEED_HEX).expect("dev seed is hex");
    KeyPair::from_seed(Seed::from_slice(&b).expect("dev seed is 32 bytes"))
}

pub fn dev_public_key() -> PublicKey {
    dev_keypair().pk
}
